// Configure search here. Each entry produces one DuckDuckGo query.
// Rotates priority EU countries; adjust the roles list to widen/narrow targeting.
const countries = ['Germany','Netherlands','France','Sweden','Denmark','Finland','Norway','United Kingdom','Malta'];
const rolesGroup = '("founder" OR "CEO" OR "owner" OR "co-founder" OR "managing director")';
const maxPerCountry = parseInt($env.DISCOVERY_PER_COUNTRY || '3', 10);

return countries.map((c) => ({
  json: {
    country: c,
    query: `site:linkedin.com/in/ ${rolesGroup} "${c}"`,
    max_results: maxPerCountry
  }
}));

// Parse DDG HTML results, extract LinkedIn /in/ profile URLs + linked text.
const html = $input.item.json.body || '';
const country = $('Loop Each Country').item.json.country;
const maxResults = $('Loop Each Country').item.json.max_results;

// DDG results look like:
//   <a rel="nofollow" class="result__a" href="//duckduckgo.com/l/?uddg=https%3A%2F%2Fwww.linkedin.com%2Fin%2Fjane-doe-1234%2F&...">Jane Doe - CEO at Acme - LinkedIn</a>
const re = /<a[^>]*class=\"result__a\"[^>]*href=\"([^\"]+)\"[^>]*>([\s\S]*?)<\/a>/gi;

const out = [];
const seen = new Set();
let m;
while ((m = re.exec(html)) !== null) {
  if (out.length >= maxResults) break;
  let href = m[1];
  const text = m[2].replace(/<[^>]+>/g, '').replace(/&amp;/g,'&').replace(/&#x27;/g,"'").trim();

  // DDG wraps real URL in uddg= param
  const uddg = href.match(/[?&]uddg=([^&]+)/);
  if (uddg) href = decodeURIComponent(uddg[1]);

  // Only LinkedIn personal profiles
  if (!/linkedin\.com\/in\//i.test(href)) continue;
  // Normalize
  const norm = href.split('?')[0].replace(/\/+$/, '');
  if (seen.has(norm)) continue;
  seen.add(norm);

  // Parse "First Last - Job at Company - LinkedIn" style text
  let firstName = '', lastName = '', jobTitle = '', companyName = '';
  const parts = text.split(/\s+[-â€“|Â·]\s+/).map((s) => s.trim()).filter(Boolean);
  // First chunk is usually the name (drop trailing "- LinkedIn")
  const cleaned = parts.filter((p) => !/^linkedin$/i.test(p));
  if (cleaned.length >= 1) {
    const nameToks = cleaned[0].split(/\s+/).filter(Boolean);
    firstName = nameToks[0] || '';
    lastName = nameToks.slice(1).join(' ') || '';
  }
  if (cleaned.length >= 2) {
    // Try "Job at Company" or "Job @ Company"
    const second = cleaned[1];
    const at = second.split(/\s+(?:at|@)\s+/i);
    if (at.length === 2) {
      jobTitle = at[0].trim();
      companyName = at[1].trim();
    } else {
      jobTitle = second;
    }
  }
  if (!companyName && cleaned.length >= 3) companyName = cleaned[2];

  if (!firstName || !/linkedin\.com\/in\//.test(norm)) continue;

  out.push({
    json: {
      first_name: firstName,
      last_name: lastName,
      job_title: jobTitle || 'Founder',
      company_name: companyName || '',
      linkedin_url: norm,
      country
    }
  });
}
return out;

// At this point each item is the dedupe SELECT result merged with prospect via pairedItem.
// Pull the prospect from the upstream 'Parse Results' node by pairedItem index.
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const prospect = $('Parse Results').all()[i];
  if (prospect) out.push(prospect);
}
return out;

// Aggregate all prospects from every iteration into a single { prospects: [...] } payload.
const all = $input.all().map((it) => it.json);
return [{ json: { prospects: all, count: all.length } }];
